// Extract funnel metrics from the unified analytics response
const body = items[0]?.json || {};
const data = body.data || body;

// Build the rollup record from the raw data
const rollup = {
  date: new Date().toISOString().slice(0, 10),
  visitors: data.uniqueVisitors || 0,
  leads: data.leads || 0,
  mql: data.marketingQualifiedLeads || 0,
  sql: data.salesQualifiedLeads || 0,
  opportunities: data.opportunities || 0,
  customers: data.customers || 0,
  revenue: data.revenue || 0,
  conversionRate: data.leads > 0 ? (data.customers / data.leads * 100).toFixed(2) : 0
};

return [{ json: rollup }];
